<?php require_once __DIR__.'/../../app/layout.php';$m=require_member();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$amount=(float)$_POST['amount'];$purpose=trim($_POST['purpose']??'');$txn=trim($_POST['transaction_no']??'');if($amount<=0||$purpose===''||!in_array($_POST['payment_mode']??'',['upi','bank','cash'],true))throw new RuntimeException('Enter valid donation details.');$pdo->prepare('INSERT INTO donations (member_id,amount,purpose,payment_mode,transaction_no,payment_date,proof_path,remarks) VALUES (?,?,?,?,?,?,?,?)')->execute([$m['id'],$amount,$purpose,$_POST['payment_mode'],$txn?:null,$_POST['payment_date'],upload('proof'),trim($_POST['remarks']??'')?:null]);flash('Donation submitted for administrator verification.');redirect('/member/dashboard.php');}catch(Throwable $e){flash('Unable to save donation. Check transaction number.','error');}}header_html('Donation');?><h1>Make a donation</h1><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Amount<input type="number" step="0.01" min="1" name="amount" required></label><label>Purpose<input name="purpose" required maxlength="255"></label><label>Mode<select name="payment_mode"><option value="upi">UPI / QR</option><option value="bank">Bank transfer</option><option value="cash">Cash</option></select></label><label>UTR / Transaction Number<input name="transaction_no"></label><label>Payment date<input type="date" name="payment_date" value="<?=date('Y-m-d')?>" required></label><label>Proof<input type="file" name="proof"></label><label>Remarks<textarea name="remarks"></textarea></label><button>Submit donation</button></form><?php footer_html();
